import Foundation

// MARK: - Circuit Breaker
enum CircuitState {
    case closed, open, halfOpen
}

class CircuitBreaker {
    private var failureCount = 0
    private var lastFailureTime: Date?
    private let threshold = 5
    private let resetTimeout: TimeInterval = 30
    private(set) var state: CircuitState = .closed

    func recordSuccess() {
        failureCount = 0
        state = .closed
    }

    func recordFailure() {
        failureCount += 1
        lastFailureTime = Date()
        if failureCount >= threshold {
            state = .open
        }
    }

    func canExecute() -> Bool {
        switch state {
        case .closed:
            return true
        case .open:
            if let lastFailure = lastFailureTime,
               Date().timeIntervalSince(lastFailure) > resetTimeout {
                state = .halfOpen
                return true
            }
            return false
        case .halfOpen:
            return true
        }
    }
}

// MARK: - Message Types
struct QueueMessage {
    let id: String
    let payload: [String: Any]
    let timestamp: Date
    let contentType: String
}

// MARK: - Content Sanitizer
class ContentSanitizer {
    private static let dangerousTags = ["script", "iframe", "object", "embed", "form"]
    private static let dangerousAttrs = ["onerror", "onload", "onclick", "onmouseover"]

    static func sanitizeHTML(_ input: String) -> String {
        var result = input
        for tag in dangerousTags {
            let pattern = "<\\s*\(tag)[^>]*>.*?<\\s*/\\s*\(tag)\\s*>"
            if let regex = try? NSRegularExpression(pattern: pattern, options: [.caseInsensitive, .dotMatchesLineSeparators]) {
                result = regex.stringByReplacingMatches(in: result, range: NSRange(result.startIndex..., in: result), withTemplate: "")
            }
        }
        for attr in dangerousAttrs {
            let pattern = "\(attr)\\s*=\\s*[\"'][^\"']*[\"']"
            if let regex = try? NSRegularExpression(pattern: pattern, options: .caseInsensitive) {
                result = regex.stringByReplacingMatches(in: result, range: NSRange(result.startIndex..., in: result), withTemplate: "")
            }
        }
        return result
    }

    static func sanitizePlainText(_ input: String) -> String {
        return input
            .replacingOccurrences(of: "&", with: "&amp;")
            .replacingOccurrences(of: "<", with: "&lt;")
            .replacingOccurrences(of: ">", with: "&gt;")
            .replacingOccurrences(of: "\"", with: "&quot;")
            .replacingOccurrences(of: "'", with: "&#x27;")
    }
}

// MARK: - Message Processor
class MessageProcessor {
    private let circuitBreaker = CircuitBreaker()
    private var processedMessages: [String: String] = [:]

    func processMessage(_ message: QueueMessage) -> Result<String, Error> {
        guard circuitBreaker.canExecute() else {
            return .failure(NSError(domain: "CircuitOpen", code: 503))
        }

        do {
            let rendered = try renderContent(message)
            processedMessages[message.id] = rendered
            circuitBreaker.recordSuccess()
            return .success(rendered)
        } catch {
            circuitBreaker.recordFailure()
            return .failure(error)
        }
    }

    private func renderContent(_ message: QueueMessage) throws -> String {
        guard let body = message.payload["body"] as? String else {
            throw NSError(domain: "InvalidPayload", code: 400)
        }

        let sanitized = applySanitization(body, contentType: message.contentType)
        let template = buildTemplate(for: message, content: sanitized)
        return template
    }

    private func applySanitization(_ content: String, contentType: String) -> String {
        let normalizedType = normalizeContentType(contentType)

        switch normalizedType {
        case "text/html":
            return ContentSanitizer.sanitizeHTML(content)
        case "text/plain":
            return ContentSanitizer.sanitizePlainText(content)
        case "application/json":
            return ContentSanitizer.sanitizePlainText(content)
        default:
            return ContentSanitizer.sanitizePlainText(content)
        }
    }

    private func normalizeContentType(_ raw: String) -> String {
        let trimmed = raw.trimmingCharacters(in: .whitespaces)
        let components = trimmed.components(separatedBy: ";")
        guard let mediaType = components.first else { return "text/plain" }
        return mediaType.lowercased().trimmingCharacters(in: .whitespaces)
    }

    private func buildTemplate(for message: QueueMessage, content: String) -> String {
        let author = message.payload["author"] as? String ?? "Unknown"
        let sanitizedAuthor = ContentSanitizer.sanitizePlainText(author)

        let displayType = resolveDisplayType(message.contentType)

        return """
        <div class="message" data-id="\(ContentSanitizer.sanitizePlainText(message.id))">
            <span class="author">\(sanitizedAuthor)</span>
            <div class="content" data-type="\(displayType)">\(content)</div>
            <time>\(message.timestamp)</time>
        </div>
        """
    }

    private func resolveDisplayType(_ contentType: String) -> String {
        let normalized = normalizeContentType(contentType)
        switch normalized {
        case "text/html":
            return "rich"
        case "text/plain":
            return "plain"
        default:
            return "plain"
        }
    }

    func getProcessedMessage(_ id: String) -> String? {
        return processedMessages[id]
    }
}

// MARK: - Queue Consumer
class MessageQueueConsumer {
    private let processor = MessageProcessor()
    private var deadLetterQueue: [QueueMessage] = []

    func consume(_ rawMessages: [[String: Any]]) -> [String] {
        var results: [String] = []

        for raw in rawMessages {
            guard let id = raw["id"] as? String,
                  let payload = raw["payload"] as? [String: Any],
                  let contentType = raw["content_type"] as? String else {
                continue
            }

            let message = QueueMessage(
                id: id,
                payload: payload,
                timestamp: Date(),
                contentType: contentType
            )

            let result = processor.processMessage(message)
            switch result {
            case .success(let html):
                results.append(html)
            case .failure:
                deadLetterQueue.append(message)
            }
        }

        return results
    }
}
